import re

with open('/tmp/dhr_10q_full.htm', 'r', encoding='utf-8') as f:
    content = f.read()

# Get all ix:nonFraction with context refs to understand which period each value belongs to
pattern = r'<ix:nonFraction[^>]*name="([^"]+)"[^>]*contextRef="([^"]+)"[^>]*>([^<]+)</ix:nonFraction>'
matches = re.findall(pattern, content)

# Group by context (period)
context_data = {}
for name, ctx, val in matches:
    if name in ['us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax',
                 'us-gaap:NetIncomeLoss', 'us-gaap:EarningsPerShareDiluted',
                 'us-gaap:GrossProfit', 'us-gaap:OperatingIncomeLoss']:
        if ctx not in context_data:
            context_data[ctx] = []
        context_data[ctx].append((name, val))

# Show Q1 2026 context (c-1 is Q1 2026 based on the XML header)
for ctx, items in sorted(context_data.items()):
    print(f"\nContext {ctx}:")
